INSERT INTO `club_news` (`news_id`, `club_id`, `title`, `summary`, `image_path`, `status`, `published_at`, `created_at`) VALUES (1, 13, 'NSBM men’s volleyball team takes UOC Vice Chancellor’s Challenge Trophy 2026', 'The NSBM men’s volleyball team won the Vice Chancellor’s Challenge Trophy Volleyball Championship 2026 organised by the University of Colombo, defeating the University of Colombo Old Boys team in the final. The NSBM women’s team earned second runners-up honours. Individual awards included Best Player (Men’s) for Ishen Thilochana and Best Attacker for Dasun Navodya.
INSERT INTO `club_news` (`news_id`, `club_id`, `title`, `summary`, `image_path`, `status`, `published_at`, `created_at`) VALUES (2, 6, 'NSBM cricket team wins the KDU Leaders’ Trophy T20 2026', 'NSBM won the KDU Leaders’ Trophy Inter-University T20 Cricket Championship 2026 after defeating SLIIT in the final. NSBM chased a target of 131 with five wickets remaining and nine balls to spare. Ushen Silva scored an unbeaten 63 and was named Player of the Final; Amoda Vidanapathirana received the Player of the Tournament award.
INSERT INTO `club_news` (`news_id`, `club_id`, `title`, `summary`, `image_path`, `status`, `published_at`, `created_at`) VALUES (3, 5, 'NSBM Chess Club concludes Inter Batch 4.0 tournament', 'The Chess Club concluded Inter Batch 4.0, an event that brought together more than 60 participants. Team Phoenix (26.1) finished first, Team A (26.2) second and Team Apex (26.1) third. The results were announced by NSBM in September 2026.
INSERT INTO `club_news` (`news_id`, `club_id`, `title`, `summary`, `image_path`, `status`, `published_at`, `created_at`) VALUES (4, 3, 'NSBM Athletics Club tops higher-education category at Mercantile Athletic Championship 2026', 'The NSBM Athletics Club won the Higher Education Category at the 41st Mercantile Athletic Championship, held from 21 to 23 August 2026 at Diyagama. Wechitha Rajapaksha also won the University Boys 100m event in 11.22 seconds and was recognised as the category’s Best Male Athlete.
INSERT INTO `club_news` (`news_id`, `club_id`, `title`, `summary`, `image_path`, `status`, `published_at`, `created_at`) VALUES (5, 4, 'NSBM inter-faculty badminton tournament 2026 announces champions', 'NSBM announced the results of its 2026 Inter-Faculty Badminton Tournament. The Faculty of Computing won the men’s championship and the Faculty of Business won the women’s championship. The tournament brought together student athletes from multiple faculties.
